DOCUMENT();
############################################################ # Load Macros ############################################################ loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "parserFormulaWithUnits.pl", "contextForm.pl", "APEX.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
